/**
 * Parity of js/rotation-converter.js with its canonical reference (#4127).
 * Golden vectors: tests/fixtures/widgets/rotation-converter.parity.json,
 * generated by `python -m scripts.generate_widget_parity` (ADR 0002 section 6).
 */
'use strict';

const fs = require('fs');
const path = require('path');
const RC = require('../js/rotation-converter.js');

const fixture = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'fixtures/widgets/rotation-converter.parity.json'), 'utf8')
);

/** ADR 0002 rule: |actual - expected| <= abs + rel * |expected|, element by element. */
function expectClose(actual, expected, tolerance, label) {
  if (Array.isArray(expected)) {
    expect(actual).toHaveLength(expected.length);
    expected.forEach((value, i) => expectClose(actual[i], value, tolerance, `${label}[${i}]`));
    return;
  }
  if (typeof expected === 'object' && expected !== null) {
    Object.keys(expected).forEach(key => {
      expectClose(actual[key], expected[key], tolerance, `${label}.${key}`);
    });
    return;
  }
  if (typeof expected === 'boolean') {
    expect(actual).toBe(expected);
    return;
  }
  const bound = tolerance.abs + tolerance.rel * Math.abs(expected);
  const error = Math.abs(actual - expected);
  if (!(error <= bound)) {
    throw new Error(`${label}: |${actual} - ${expected}| = ${error} > ${bound}`);
  }
}

describe('rotation-converter parity fixture', () => {
  test('declares the v1 schema and cites the Python reference source', () => {
    expect(fixture.schema).toBe('affinedrift/widget-parity/v1');
    expect(fixture.widget).toBe('rotation-converter');
    expect(fixture.source).toBe('src/tools/rotation_reference_examples.py::rotation_to_quaternion');
    expect(fixture.tolerance).toEqual({ abs: 1e-12, rel: 1e-12 });
  });

  test.each(fixture.cases.map(c => [c.id, c]))('quaternion conversion parity %s', (_id, c) => {
    const tolerance = c.tolerance || fixture.tolerance;
    const R = RC.quaternionToR(c.inputs.quaternion);
    expectClose(R, c.expected.R, tolerance, 'quaternionToR');

    const q = RC.rToQuaternion(c.inputs.R);
    expectClose(q, c.expected.quaternion, tolerance, 'rToQuaternion');
  });

  test.each(fixture.cases.map(c => [c.id, c]))('axis-angle conversion parity %s', (_id, c) => {
    const tolerance = c.tolerance || fixture.tolerance;
    const R = RC.axisAngleToR(c.inputs.axisAngle.axis, c.inputs.axisAngle.angle);
    expectClose(R, c.expected.R, tolerance, 'axisAngleToR');

    const aa = RC.rToAxisAngle(c.inputs.R);
    expectClose(aa.axis, c.expected.axisAngle.axis, tolerance, 'rToAxisAngle.axis');
    expectClose(aa.angle, c.expected.axisAngle.angle, tolerance, 'rToAxisAngle.angle');
  });

  test.each(fixture.cases.map(c => [c.id, c]))('Euler ZYX conversion parity %s', (_id, c) => {
    const tolerance = c.tolerance || fixture.tolerance;
    const e = c.inputs.eulerZYX;
    const R = RC.eulerZYXToR(e.psi, e.theta, e.phi);
    expectClose(R, c.expected.R, tolerance, 'eulerZYXToR');

    const euler = RC.rToEulerZYX(c.inputs.R);
    expectClose(euler.psi, c.expected.eulerZYX.psi, tolerance, 'rToEulerZYX.psi');
    expectClose(euler.theta, c.expected.eulerZYX.theta, tolerance, 'rToEulerZYX.theta');
    expectClose(euler.phi, c.expected.eulerZYX.phi, tolerance, 'rToEulerZYX.phi');
    expect(euler.gimbalLock).toBe(c.expected.eulerZYX.gimbalLock);
  });

  test.each(fixture.cases.map(c => [c.id, c]))('exponential coordinates parity %s', (_id, c) => {
    const tolerance = c.tolerance || fixture.tolerance;
    const R = RC.expCoordToR(c.inputs.expCoord);
    expectClose(R, c.expected.R, tolerance, 'expCoordToR');

    const exp = RC.rToExpCoord(c.inputs.R);
    expectClose(exp, c.expected.expCoord, tolerance, 'rToExpCoord');
  });

  test.each(fixture.cases.map(c => [c.id, c]))('unified convert() parity %s', (_id, c) => {
    const tolerance = c.tolerance || fixture.tolerance;
    const fromQ = RC.convert(c.inputs.quaternion, 'quaternion');
    expectClose(fromQ.R, c.expected.R, tolerance, 'convert(quaternion).R');
    expectClose(fromQ.quaternion, c.expected.quaternion, tolerance, 'convert(quaternion).quaternion');

    const fromR = RC.convert(c.inputs.R, 'R');
    expectClose(fromR.quaternion, c.expected.quaternion, tolerance, 'convert(R).quaternion');
    expectClose(fromR.axisAngle.angle, c.expected.axisAngle.angle, tolerance, 'convert(R).axisAngle.angle');

    const fromAA = RC.convert(c.inputs.axisAngle, 'axisAngle');
    expectClose(fromAA.R, c.expected.R, tolerance, 'convert(axisAngle).R');

    const fromEuler = RC.convert(c.inputs.eulerZYX, 'eulerZYX');
    expectClose(fromEuler.R, c.expected.R, tolerance, 'convert(eulerZYX).R');

    const fromExp = RC.convert(c.inputs.expCoord, 'expCoord');
    expectClose(fromExp.R, c.expected.R, tolerance, 'convert(expCoord).R');
  });
});
